#!/usr/bin/env python3
"""Render the checked-in feature reference from the machine-readable catalog."""
import argparse
import hashlib
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
raw = (root / 'internal/features/catalog.json').read_bytes().replace(b'\r\n', b'\n')
doc = json.loads(raw)
commands = {c['id']: c['name'] for c in json.loads((root / 'internal/catalog/upstream.json').read_text(encoding='utf-8'))['commands']}
lines = [
    '# Feature catalog reference', '',
    '<!-- Generated by scripts/generate_features.py; do not edit. -->',
    '<!-- Catalog SHA256: ' + hashlib.sha256(raw).hexdigest() + ' -->', '',
    'Schema version: ' + str(doc['schema_version']) + '. This is a workflow inventory, not a count of complete hardware capabilities.', '',
    'See [capability evaluation](feature-capabilities.md) for states, parameter resolution, policy and snapshot limits.', '',
]
def names(ids):
    return ', '.join('`' + str(c) + ' ' + commands[c] + '`' for c in ids) or 'None'
for f in doc['features']:
    lines += ['## ' + f['id'] + ' — ' + f['title'], '']
    for surface in ('web', 'cli', 'sdk'):
        e = f[surface]
        lines += ['- ' + surface.upper() + ': **' + e['status'] + '**. ' + '; '.join('`' + s + '`' for s in e['entries'])]
    lines += ['', 'Models: ' + ', '.join(f['models']) + (' (device-independent)' if not f['device'] else '') + '.',
              'Transport policy: `' + f['transport'] + '`. Effect: `' + f['effect'] + '`.',
              'Requirement mode: `' + f['requirement_mode'] + '`. Unconditional commands: ' + names(f['commands']) + '.', '']
    for c in f['conditional']:
        lines += ['- ' + c['when'] + ': ' + names(c['commands'])]
    if f['conditional']: lines += ['']
    for note in f['notes']: lines += [note, '']
    lines += ['Sources: ' + ', '.join('[' + s + '](../' + s + ')' for s in f['sources']) + '.', '']
text = '\n'.join(lines) + '\n'
output = root / 'docs/features.md'
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--check', action='store_true')
args = parser.parse_args()
if args.check:
    if not output.exists() or output.read_text(encoding="utf-8") != text:
        raise SystemExit('docs/features.md is stale; run python3 scripts/generate_features.py')
else:
    output.write_text(text, encoding="utf-8", newline="\n")
